function drAudioFormat(string $tmp,string $browserMime,string $original):?array{$detected='';try{$detected=(string)(new finfo(FILEINFO_MIME_TYPE))->file($tmp);}catch(Throwable $e){}$mime=strtolower(trim(explode(';',$detected?:$browserMime)[0]));$browser=strtolower(trim(explode(';',$browserMime)[0]));$ext=strtolower(pathinfo($original,PATHINFO_EXTENSION));$map=['audio/webm'=>['webm','audio/webm'],'video/webm'=>['webm','audio/webm'],'application/webm'=>['webm','audio/webm'],'audio/ogg'=>['ogg','audio/ogg'],'application/ogg'=>['ogg','audio/ogg'],'audio/mpeg'=>['mp3','audio/mpeg'],'audio/mp3'=>['mp3','audio/mpeg'],'audio/mp4'=>['m4a','audio/mp4'],'video/mp4'=>['m4a','audio/mp4'],'application/mp4'=>['m4a','audio/mp4'],'audio/x-m4a'=>['m4a','audio/mp4'],'audio/m4a'=>['m4a','audio/mp4'],'audio/aac'=>['aac','audio/aac'],'audio/x-aac'=>['aac','audio/aac'],'audio/wav'=>['wav','audio/wav'],'audio/x-wav'=>['wav','audio/wav'],'audio/wave'=>['wav','audio/wav'],'audio/vnd.wave'=>['wav','audio/wav']];foreach([$mime,$browser] as $m){if(isset($map[$m]))return $map[$m];}$byExt=['webm'=>['webm','audio/webm'],'ogg'=>['ogg','audio/ogg'],'oga'=>['ogg','audio/ogg'],'mp3'=>['mp3','audio/mpeg'],'m4a'=>['m4a','audio/mp4'],'mp4'=>['m4a','audio/mp4'],'aac'=>['aac','audio/aac'],'wav'=>['wav','audio/wav']];return $byExt[$ext]??null;}
