?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Parte diario · Punto ERP</title><style><?=erpSidebarCss()?>body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}.main{margin-left:var(--sidebar);padding:24px 4%;max-width:900px}.card{background:#fff;border:1px solid var(--line);border-radius:16px;padding:20px;margin-bottom:15px}.hero{background:#171b20;color:#fff}.muted{color:var(--muted)}label{display:block;font-weight:750;margin:14px 0 6px}input,textarea{width:100%;box-sizing:border-box;padding:12px;border:1px solid #cbd1d7;border-radius:10px;font:inherit}textarea{min-height:130px;resize:vertical}.btn{border:0;border-radius:10px;padding:12px 16px;background:var(--o);color:#fff;font-weight:800;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;justify-content:center}.light{background:#edf0f3;color:var(--ink)}.finish{background:#18794e}.actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:18px}.flash,.warn,.info{padding:12px;border-radius:10px;margin-bottom:12px}.flash{background:#eaf8f1;border:1px solid #b9e2cd}.warn{background:#fff7e6;border:1px solid #f0d49a}.info{background:#eef5ff;border:1px solid #bfd3ef}.rec{padding:14px;border:1px solid var(--line);border-radius:12px;background:#f7f8f9}.rec.recording{border-color:#d9534f;background:#fff5f5}.audio-row{margin:10px 0}.badge{display:inline-block;padding:5px 9px;border-radius:999px;background:#edf0f3;font-size:12px}@media(max-width:900px){.main{margin-left:0;padding:14px 12px 90px}.actions .btn{flex:1}}</style></head><body><?php erpSidebar('my_day');?><main class="main"><section class="card hero"><span class="badge"><?=drE(ucfirst($event['status']))?></span><h1>Parte diario</h1><b><?=drE($event['project_number'].' · '.$event['project_name'])?></b><div><?=drE($event['business_name'])?> · <?=drE(date('d/m/Y',strtotime($event['work_date'])))?> · <?=drE($from.' – '.$to)?></div></section><?php if($msg):?><div class="flash"><?=drE($msg)?></div><?php endif;?><?php if($warn):?><div class="warn"><?=drE($warn)?></div><?php endif;?><div id="transStatus"></div><form method="post" enctype="multipart/form-data" class="card"><input type="hidden" name="csrf" value="<?=drE($_SESSION['csrf'])?>"><input type="hidden" name="event_id" value="<?=$eventId?>"><label>Horas trabajadas</label><input type="number" name="hours_worked" min="0" max="24" step="0.25" value="<?=drE($report['hours_worked']??'')?>" placeholder="Ej.: 8" required><label>Parte diario / trabajo realizado</label><textarea name="report_text" placeholder="Podés escribir algo o simplemente grabar el audio."><?=drE($report['report_text']??'')?></textarea><label>Audio del parte</label><div class="rec" id="recBox"><p class="muted">Grabalo desde el celular. El parte se guarda primero y la transcripción se procesa después, para evitar que se corte la página.</p><div class="actions"><button type="button" class="btn" id="recordBtn">● Grabar audio</button><button type="button" class="btn light" id="stopBtn" disabled>■ Detener</button></div><div id="preview"></div><input type="file" name="audio" id="audioFile" accept="audio/*,.webm,.m4a,.mp4,.aac,.ogg,.mp3,.wav" style="margin-top:12px"></div><label>Transcripción automática</label><textarea name="transcription" id="transcription" placeholder="La transcripción aparecerá acá."><?=drE($report['transcription']??'')?></textarea><?php if($latestAudio&&$aiReady):?><div class="actions"><button class="btn light" type="button" id="transcribeBtn">Transcribir último audio</button></div><?php endif;?><?php if($audios):?><div style="margin-top:15px"><b>Audios guardados</b><?php foreach($audios as $au):?><div class="audio-row">🎙 <?=drE($au['original_name']?:basename($au['file_path']))?> <span class="muted"><?=drE(date('d/m/Y H:i',strtotime($au['created_at'])))?></span></div><?php endforeach;?></div><?php endif;?><div class="