let recorder,chunks=[],stream;const rb=document.getElementById('recordBtn'),sb=document.getElementById('stopBtn'),box=document.getElementById('recBox'),preview=document.getElementById('preview'),file=document.getElementById('audioFile');if(!navigator.mediaDevices||!window.MediaRecorder){rb.disabled=true;rb.textContent='Grabación no disponible';}rb.onclick=async()=>{try{stream=await navigator.mediaDevices.getUserMedia({audio:true});chunks=[];let opts={};if(MediaRecorder.isTypeSupported&&MediaRecorder.isTypeSupported('audio/webm;codecs=opus'))opts={mimeType:'audio/webm;codecs=opus'};else if(MediaRecorder.isTypeSupported&&MediaRecorder.isTypeSupported('audio/mp4'))opts={mimeType:'audio/mp4'};recorder=new MediaRecorder(stream,opts);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{const type=recorder.mimeType||chunks[0]?.type||'audio/webm',blob=new Blob(chunks,{type}),ext=type.includes('mp4')?'m4a':type.includes('ogg')?'ogg':type.includes('mpeg')?'mp3':'webm',f=new File([blob],'parte-diario-'+Date.now()+'.'+ext,{type}),dt=new DataTransfer();dt.items.add(f);file.files=dt.files;preview.innerHTML='';const audio=document.createElement('audio');audio.controls=true;audio.src=URL.createObjectURL(blob);preview.appendChild(audio);stream.getTracks().forEach(t=>t.stop());box.classList.remove('recording');rb.disabled=false;sb.disabled=true;rb.textContent='● Grabar audio'};recorder.start();box.classList.add('recording');rb.disabled=true;sb.disabled=false;rb.textContent='Grabando…'}catch(e){alert('No se pudo acceder al micrófono. Revisá el permiso del navegador.')}};sb.onclick=()=>{if(recorder&&recorder.state!=='inactive')recorder.stop()};
const latestAudioId=<?=json_encode((int)($latestAudio['id']??0))?>, aiReady=<?=json_encode($aiReady)?>, trans=document.getElementById('transcription'),statusBox=document.getElementById('transStatus'),tb=document.getElementById('transcribeBtn');async function transcribe(){if(!latestAudioId||!aiReady)return;if(tb)tb.disabled=true;statusBox.innerHTML='<div class="info">Transcribiendo audio… podés seguir en esta pantalla.</div>';try{const fd=new FormData();fd.append('audio_id',latestAudioId);const res=await fetch('?a=transcribe_report',{method:'POST',body:fd,credentials:'same-origin'});let data;try{data=await res.json()}catch(e){throw new Error('El servidor cerró la conexión durante la transcripción.');}if(!res.ok||!data.ok)throw new Error(data.error||'No se pudo transcribir.');trans.value=data.text;statusBox.innerHTML='<div class="flash">Audio transcripto correctamente.</div>';}catch(e){statusBox.innerHTML='<div class="warn">No se pudo transcribir: '+String(e.message||e)+'</div>';}finally{if(tb)tb.disabled=false;}}if(tb)tb.onclick=transcribe;if(latestAudioId&&aiReady&&!trans.value.trim())setTimeout(transcribe,500);
</script></body></html>